insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','Verb past plain form + ことがある describes a past experience. 行ったことがあります means ‘have been’. The other nouns do not form this experience pattern.','「{動詞|どうし}のた{形|けい}＋ことがある」は、{経験|けいけん}を{表|あらわ}します。','I have been to Japan.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','{毎朝|まいあさ}、{音楽|おんがく}を{聞|き}き ___ {朝|あさ}ご{飯|はん}を{作|つく}ります。',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000005','40000000-0000-4000-8000-000000000002','まで',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000006','40000000-0000-4000-8000-000000000002','ながら',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000007','40000000-0000-4000-8000-000000000002','ため',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000008','40000000-0000-4000-8000-000000000002','ほど',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000006','Attach ながら to the verb’s ます-stem: 聞きます → 聞きながら. It expresses two simultaneous actions by the same person; the main action follows.','「{動詞|どうし}のます{形|けい}の{語幹|ごかん}＋ながら」は、{二|ふた}つの{動作|どうさ}を{同時|どうじ}にすることを{表|あらわ}します。','Every morning, I make breakfast while listening to music.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000001','{宿題|しゅくだい}をして ___ 、テレビを{見|み}ます。',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000009','40000000-0000-4000-8000-000000000003','まで',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000010','40000000-0000-4000-8000-000000000003','より',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000011','40000000-0000-4000-8000-000000000003','から',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000012','40000000-0000-4000-8000-000000000003','ほど',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000003','50000000-0000-4000-8000-000000000011','Verb て-form + から places the second action after completion of the first. してから means ‘after doing’. The other options cannot follow して in this sentence.','「て{形|けい}＋から」は、{先|さき}にすることと、その{後|あと}にすることの{順番|じゅんばん}を{表|あらわ}します。','I will watch TV after doing my homework.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000004','30000000-0000-4000-8000-000000000001','ここで{写真|しゃしん}を{撮|と}って ___ ですか。',3) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000013','40000000-0000-4000-8000-000000000004','ある',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000014','40000000-0000-4000-8000-000000000004','いる',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000015','40000000-0000-4000-8000-000000000004','する',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000016','40000000-0000-4000-8000-000000000004','もいい',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000004','50000000-0000-4000-8000-000000000016','Verb て-form + もいいですか asks permission. 撮ってもいいですか means ‘May I take a photograph?’ The other choices do not form a permission question.','「て{形|けい}＋もいいですか」は、{許可|きょか}を{求|もと}める{表現|ひょうげん}です。','May I take a photograph here?') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000005','30000000-0000-4000-8000-000000000001','{明日|あした}は{試験|しけん}ですから、{勉強|べんきょう}しなければ ___ 。',4) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000017','40000000-0000-4000-8000-000000000005','なりません',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000018','40000000-0000-4000-8000-000000000005','ありません',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000019','40000000-0000-4000-8000-000000000005','できません',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000020','40000000-0000-4000-8000-000000000005','しません',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000005','50000000-0000-4000-8000-000000000017','Verb ない-form without い + ければなりません expresses obligation. しなければなりません means ‘must do’. なりません completes this fixed construction.','「なければなりません」は、{必要|ひつよう}なことや{義務|ぎむ}を{表|あらわ}します。','I have an exam tomorrow, so I must study.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000006','30000000-0000-4000-8000-000000000001','{病気|びょうき}なので、{今日|きょう}は{学校|がっこう}を{休|やす}む ___ です。',5) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000021','40000000-0000-4000-8000-000000000006','ながら',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000022','40000000-0000-4000-8000-000000000006','つもり',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000023','40000000-0000-4000-8000-000000000006','だけで',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000024','40000000-0000-4000-8000-000000000006','までに',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000006','50000000-0000-4000-8000-000000000022','Verb dictionary form + つもりです states an intention. 休むつもりです means ‘intend to be absent’. ながら requires a ます-stem; the other choices do not form the required predicate.','「{辞書形|じしょけい}＋つもりです」は、{自分|じぶん}の{意志|いし}や{予定|よてい}を{表|あらわ}します。','Because I am ill, I intend to stay home from school today.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000007','30000000-0000-4000-8000-000000000001','この{本|ほん}は{字|じ}が{大|おお}きくて、{読|よ}み ___ です。',6) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000025','40000000-0000-4000-8000-000000000007','ながら',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000026','40000000-0000-4000-8000-000000000007','たいな',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000027','40000000-0000-4000-8000-000000000007','やすい',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000028','40000000-0000-4000-8000-000000000007','すぎな',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000007','50000000-0000-4000-8000-000000000027','Verb ます-stem + やすい means ‘easy to do’. 読みやすい describes readability. ながら cannot be followed by です this way; たいな and すぎな are not valid endings here.','「ます{形|けい}の{語幹|ごかん}＋やすい」は、その{動作|どうさ}が{簡単|かんたん}だという{意味|いみ}です。','This book has large print and is easy to read.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000008','30000000-0000-4000-8000-000000000001','{昨日|きのう}、ケーキを{食|た}べ ___ 、おなかが{痛|いた}くなりました。',7) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000029','40000000-0000-4000-8000-000000000008','すぎます',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000030','40000000-0000-4000-8000-000000000008','すぎた',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000031','40000000-0000-4000-8000-000000000008','すぎる',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000032','40000000-0000-4000-8000-000000000008','すぎて',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000008','50000000-0000-4000-8000-000000000032','Verb ます-stem + すぎる means ‘do too much’. Its て-form, すぎて, links the excessive eating to the consequence. The sentence describes excess, not ease, appearance, or simultaneous actions.','「ます{形|けい}の{語幹|ごかん}＋すぎる」は、{程度|ていど}が{多|おお}すぎることを{表|あらわ}します。','Yesterday I ate too much cake and got a stomachache.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000009','30000000-0000-4000-8000-000000000001','{雨|あめ}が{降|ふ}り ___ ですから、{傘|かさ}を{持|も}っていきましょう。',8) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000033','40000000-0000-4000-8000-000000000009','そう',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000034','40000000-0000-4000-8000-000000000009','ながら',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000035','40000000-0000-4000-8000-000000000009','たいな',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000036','40000000-0000-4000-8000-000000000009','やすく',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000009','50000000-0000-4000-8000-000000000033','Verb ます-stem + そうです expresses an appearance or imminent event based on what one observes. 降りそうです means ‘looks like it will rain’. The verb stem cannot take the other choices here.','「ます{形|けい}の{語幹|ごかん}＋そうです」は、{見|み}た{様子|ようす}から{判断|はんだん}する{表現|ひょうげん}です。','It looks as though it will rain, so let’s take an umbrella.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000010','30000000-0000-4000-8000-000000000001','{日本語|にほんご}が{上手|じょうず}に{話|はな}せる ___ なりたいです。',9) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000037','40000000-0000-4000-8000-000000000010','ために',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000038','40000000-0000-4000-8000-000000000010','ように',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000039','40000000-0000-4000-8000-000000000010','ことに',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000040','40000000-0000-4000-8000-000000000010','そうに',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000010','50000000-0000-4000-8000-000000000038','Potential verb + ようになる expresses gaining an ability. 話せるようになりたい means ‘want to become able to speak’. The other choices do not express this change in ability.','「{可能|かのう}{動詞|どうし}＋ようになる」は、できなかったことができる{変化|へんか}を{表|あらわ}します。','I want to become able to speak Japanese well.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000011','30000000-0000-4000-8000-000000000001','{旅行|りょこう}に{行|い}く{前|まえ}に、ホテルを{予約|よやく}して ___ ます。',10) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000041','40000000-0000-4000-8000-000000000011','おき',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000042','40000000-0000-4000-8000-000000000011','おいて',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000043','40000000-0000-4000-8000-000000000011','おく',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000044','40000000-0000-4000-8000-000000000011','おこう',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000011','50000000-0000-4000-8000-000000000041','Verb て-form + おく describes preparation for later. Its polite form is ておきます. Here 予約しておきます means “reserve in advance”. Only おき connects to the printed ます ending.','「て{形|けい}＋おく」は、{後|あと}のために{準備|じゅんび}することを{表|あらわ}します。','I will reserve a hotel in advance before the trip.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000012','30000000-0000-4000-8000-000000000001','{財布|さいふ}をなくして ___ 、{困|こま}っています。',11) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000045','40000000-0000-4000-8000-000000000012','みて',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000046','40000000-0000-4000-8000-000000000012','おいて',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000047','40000000-0000-4000-8000-000000000012','あって',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000048','40000000-0000-4000-8000-000000000012','しまって',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000012','50000000-0000-4000-8000-000000000048','Verb て-form + しまう can express an unwanted completed event and regret. なくしてしまって links accidentally losing the wallet to the resulting difficulty. The other forms do not express this unintended loss naturally.','「て{形|けい}＋しまう」は、{残念|ざんねん}な{結果|けっか}になった{気持|きも}ちを{表|あらわ}すことがあります。','I lost my wallet, and I am in trouble.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000013','30000000-0000-4000-8000-000000000001','{時間|じかん}が ___ 、{一緒|いっしょ}に{映画|えいが}を{見|み}に{行|い}きませんか。',12) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000049','40000000-0000-4000-8000-000000000013','あれば',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000050','40000000-0000-4000-8000-000000000013','あるときで',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000051','40000000-0000-4000-8000-000000000013','あったり',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000052','40000000-0000-4000-8000-000000000013','ありながらの',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000013','50000000-0000-4000-8000-000000000049','The conditional ば form of ある is あれば. It provides the condition ‘if there is time’. The remaining forms cannot connect grammatically to this invitation as printed.','「あれば」は「ある」の{条件形|じょうけんけい}です。{条件|じょうけん}を{示|しめ}します。','If you have time, would you like to go see a movie together?') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000014','30000000-0000-4000-8000-000000000001','{安|やす}い ___ 、このかばんを{買|か}います。',13) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000053','40000000-0000-4000-8000-000000000014','のでに',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000054','40000000-0000-4000-8000-000000000014','なら',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000055','40000000-0000-4000-8000-000000000014','ながら',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000056','40000000-0000-4000-8000-000000000014','ためで',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000014','50000000-0000-4000-8000-000000000054','い-adjective + なら gives a condition or assumption: 安いなら means ‘if it is cheap’. The other supplied expressions cannot follow 安い in this sentence.','「なら」は、{相手|あいて}の{話|はなし}や{仮定|かてい}を{条件|じょうけん}にする{表現|ひょうげん}です。','If it is inexpensive, I will buy this bag.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000015','30000000-0000-4000-8000-000000000001','{日曜日|にちようび}は、{掃除|そうじ}をしたり、{洗濯|せんたく}を ___ します。',14) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000057','40000000-0000-4000-8000-000000000015','するから',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000058','40000000-0000-4000-8000-000000000015','しても',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000059','40000000-0000-4000-8000-000000000015','したり',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000060','40000000-0000-4000-8000-000000000015','しながら',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000015','50000000-0000-4000-8000-000000000059','Verb た-form + り lists representative activities. したり、したりします pairs examples, so 洗濯をしたり completes the list. Other choices break the paired listing construction.','「たり、たりする」は、いくつかの{動作|どうさ}を{例|れい}として{挙|あ}げます。','On Sundays, I do things such as cleaning and laundry.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000016','30000000-0000-4000-8000-000000000001','{駅|えき}に{着|つ}いた ___ 、{電話|でんわ}してください。',15) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000061','40000000-0000-4000-8000-000000000016','ながら',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000062','40000000-0000-4000-8000-000000000016','ために',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000063','40000000-0000-4000-8000-000000000016','ように',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000064','40000000-0000-4000-8000-000000000016','ら',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000016','50000000-0000-4000-8000-000000000064','Verb past form + ら creates the たら conditional: 着いた + ら → 着いたら. It can mark a future condition (‘when you arrive’). The other options cannot attach to 着いた here.','「た{形|けい}＋ら」は、あることが{起|お}きた{後|あと}の{条件|じょうけん}を{表|あらわ}します。','Please call me when you arrive at the station.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000017','30000000-0000-4000-8000-000000000001','{明日|あした}は{早|はや}く{起|お}きるので、もう{寝|ね}た ___ いいです。',16) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000065','40000000-0000-4000-8000-000000000017','ほうが',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000066','40000000-0000-4000-8000-000000000017','ことが',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000067','40000000-0000-4000-8000-000000000017','ものが',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000068','40000000-0000-4000-8000-000000000017','ためが',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000017','50000000-0000-4000-8000-000000000065','Verb た-form + ほうがいい gives advice. 寝たほうがいい means ‘had better go to bed’. The other nouns do not form this advice pattern.','「た{形|けい}＋ほうがいい」は、{助言|じょげん}をする{表現|ひょうげん}です。','Since you will get up early tomorrow, you should go to bed now.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000018','30000000-0000-4000-8000-000000000001','この{料理|りょうり}を{一度|いちど}{食|た}べて ___ ください。',17) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000069','40000000-0000-4000-8000-000000000018','みます',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000070','40000000-0000-4000-8000-000000000018','みて',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000071','40000000-0000-4000-8000-000000000018','みる',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000072','40000000-0000-4000-8000-000000000018','みた',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000018','50000000-0000-4000-8000-000000000070','Verb て-form + みる means ‘try doing something’. 食べてみてください asks someone to try the dish. The other auxiliaries do not express this trial naturally.','「て{形|けい}＋みる」は、{試|ため}しにすることを{表|あらわ}します。','Please try eating this dish once.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000019','30000000-0000-4000-8000-000000000001','{母|はは}は{私|わたし}にセーターを{編|あ}んで ___ 。',18) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000073','40000000-0000-4000-8000-000000000019','あげました',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000074','40000000-0000-4000-8000-000000000019','もらいました',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000075','40000000-0000-4000-8000-000000000019','くれました',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000076','40000000-0000-4000-8000-000000000019','ありました',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000019','50000000-0000-4000-8000-000000000075','Verb て-form + くれる describes someone doing something for the speaker (or the speaker’s in-group). 母 is the giver and 私 is the beneficiary. もらう would require the receiver as subject; あげる points away from the speaker.','「て{形|けい}＋くれる」は、ほかの{人|ひと}が{私|わたし}のためにすることを{表|あらわ}します。','My mother knitted a sweater for me.') on conflict do nothing;
insert into public.questions(id,bank_id,prompt,position) values('40000000-0000-4000-8000-000000000020','30000000-0000-4000-8000-000000000001','{子供|こども}のとき、{野菜|やさい}が{嫌|きら}いでしたが、{今|いま}は{食|た}べられる ___ なりました。',19) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000077','40000000-0000-4000-8000-000000000020','そうに',0) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000078','40000000-0000-4000-8000-000000000020','ために',1) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000079','40000000-0000-4000-8000-000000000020','ことに',2) on conflict do nothing;
insert into public.question_options(id,question_id,text,position) values('50000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000020','ように',3) on conflict do nothing;
insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values('40000000-0000-4000-8000-000000000020','50000000-0000-4000-8000-000000000080','Potential form + ようになる indicates a change in ability. 食べられるようになりました means ‘became able to eat’. ことになる expresses a decision or arrangement rather than this acquired ability.','「{可能形|かのうけい}＋ようになる」は、{能力|のうりょく}の{変化|へんか}を{表|あらわ}します。','I disliked vegetables as a child, but now I have become able to eat them.') on conflict do nothing;
